// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Token token;
    SigMaker maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new Token();
        maker = new SigMaker();
    }

    function testFuzz_property(uint256 nonce, uint256 duration, uint256 expiryOffset) public {
        duration = bound(duration, 0, 9_999 days);
        expiryOffset = bound(expiryOffset, 1, type(uint64).max);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + expiryOffset,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        uint256 positionId = c.fillOrder(order, hex"", floorAssetTokenIds);

        // General rule: every successfully minted position NFT has a recorded owner,
        // in particular the taker owns the opposite-side position minted to them.
        bool ok;
        try c.ownerOf(positionId) returns (address owner) {
            ok = (owner == address(this));
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract SigMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

contract Token {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
